create table public.agent_events (chat_id uuid not null, created_at timestamptz not null default now(), detail jsonb default '{}'::jsonb not null, event_type text not null, id bigint generated by default as identity primary key, job_id uuid, project_id uuid not null, status text default 'ok' not null, title text not null, user_id uuid not null);
