create table public.agent_jobs (attempts integer default 0 not null, available_at timestamptz not null default now(), cancel_requested_at timestamptz, chat_id uuid not null, checkpoint_id uuid, created_at timestamptz not null default now(), finished_at timestamptz, heartbeat_at timestamptz, id uuid primary key default gen_random_uuid(), last_error text, lease_generation integer default 0 not null, max_attempts integer default 3 not null, plan_id uuid not null, project_id uuid not null, started_at timestamptz, status text default 'queued' not null, updated_at timestamptz not null default now(), user_id uuid not null, worker_id text, unique (plan_id));
create table public.agent_plans (approved_at timestamptz, chat_id uuid not null, created_at timestamptz not null default now(), goal text not null, id uuid primary key default gen_random_uuid(), plan jsonb not null, plan_hash text not null, project_id uuid not null, status text default 'pending' not null, user_id uuid not null, version integer not null);
