create or replace function public.owns_project(_project_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.projects where id = _project_id and user_id = auth.uid())
$$;
create or replace function public.owns_cognitive_motor(_motor_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.cognitive_motors where id = _motor_id and user_id = auth.uid())
$$;

grant all on public.agent_job_checkpoints to service_role;
grant select on public.agent_job_checkpoints to authenticated;
alter table public.agent_job_checkpoints enable row level security;
create policy own_select on public.agent_job_checkpoints for select to authenticated using (user_id = auth.uid());
grant all on public.agent_jobs to service_role;
grant select on public.agent_jobs to authenticated;
alter table public.agent_jobs enable row level security;
create policy own_select on public.agent_jobs for select to authenticated using (user_id = auth.uid());
grant all on public.api_connections to service_role;
grant select (created_at, google_project, id, is_active, is_primary, last_error, last_tested_at, metadata, model, name, provider, quota_exceeded_at, secret_hint, status, updated_at, user_id) on public.api_connections to authenticated;
grant delete on public.api_connections to authenticated;
alter table public.api_connections enable row level security;
create policy own_select on public.api_connections for select to authenticated using (user_id = auth.uid());
create policy own_delete on public.api_connections for delete to authenticated using (user_id = auth.uid());
grant all on public.migration_history to service_role;
alter table public.migration_history enable row level security;
grant all on public.profiles to service_role;
