create policy own_profile_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy own_profile_update on public.profiles for update to authenticated using (id = auth.uid());

grant all on public.agent_events, public.agent_plans, public.agent_sessions, public.audit_logs, public.chat_messages, public.chats, public.checkpoints, public.cognitive_conversations, public.cognitive_documents, public.cognitive_file_contents, public.cognitive_knowledge, public.cognitive_knowledge_sources, public.cognitive_learning_events, public.cognitive_memory_index, public.cognitive_messages, public.cognitive_motor_settings, public.cognitive_motors, public.deployment_domains, public.deployment_logs, public.deployments, public.development_logs, public.development_tasks, public.file_changes, public.preview_logs, public.preview_sessions, public.project_memory, public.projects, public.publication_releases, public.publications, public.repositories, public.repository_snapshots, public.site_records, public.test_results to service_role;
grant select, insert, update on public.cognitive_conversations, public.cognitive_documents, public.cognitive_file_contents, public.cognitive_knowledge, public.cognitive_knowledge_sources, public.cognitive_learning_events, public.cognitive_memory_index, public.cognitive_messages, public.cognitive_motor_settings, public.cognitive_motors to authenticated;
grant select, insert, update, delete on public.agent_events, public.agent_plans, public.agent_sessions, public.audit_logs, public.chat_messages, public.chats, public.checkpoints, public.deployment_domains, public.deployment_logs, public.deployments, public.development_logs, public.development_tasks, public.file_changes, public.preview_logs, public.preview_sessions, public.project_memory, public.projects, public.publication_releases, public.publications, public.repositories, public.repository_snapshots, public.site_records, public.test_results to authenticated;

do $$
declare t text; chk text;
begin
  foreach t in array array['agent_events','agent_plans','agent_sessions','audit_logs','chat_messages','chats','checkpoints','cognitive_conversations','cognitive_documents','cognitive_file_contents','cognitive_knowledge','cognitive_knowledge_sources','cognitive_learning_events','cognitive_memory_index','cognitive_messages','cognitive_motor_settings','cognitive_motors','deployment_domains','deployment_logs','deployments','development_logs','development_tasks','file_changes','preview_logs','preview_sessions','project_memory','projects','publication_releases','publications','repositories','repository_snapshots','site_records','test_results'] loop
    execute format('alter table public.%I enable row level security', t);
    chk := case when t = any(array['agent_events','agent_plans','agent_sessions','audit_logs','chats','checkpoints','development_logs','development_tasks','file_changes','project_memory','repositories','repository_snapshots','test_results']) then 'user_id = auth.uid() and (project_id is null or public.owns_project(project_id))' else 'user_id = auth.uid()' end;
    if t not like 'cognitive\_%' then
      execute format('create policy own_delete on public.%I for delete to authenticated using (user_id = auth.uid())', t);
    end if;
    execute format('create policy own_select on public.%I for select to authenticated using (user_id = auth.uid())', t);
    execute format('create policy own_insert on public.%I for insert to authenticated with check (%s)', t, chk);
    execute format('create policy own_update on public.%I for update to authenticated using (user_id = auth.uid()) with check (%s)', t, chk);
  end loop;
end $$;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, display_name, avatar_url)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', split_part(new.email,'@',1)), new.raw_user_meta_data->>'avatar_url')
  on conflict (id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create or replace function public.acquire_agent_lock(_chat_id uuid, _stale_seconds integer default 120) returns text
language plpgsql security definer set search_path = public as $$
declare _uid uuid := auth.uid(); _chat record; _s record; _token text := gen_random_uuid()::text;
begin
  if _uid is null then raise exception 'not authenticated'; end if;
  select id, project_id into _chat from public.chats where id = _chat_id and user_id = _uid;
  if not found then raise exception 'chat not found'; end if;
  select * into _s from public.agent_sessions where chat_id = _chat_id for update;
  if found then
    if _s.status = 'running' and _s.heartbeat_at > now() - make_interval(secs => _stale_seconds) then return null; end if;
    update public.agent_sessions set status='running', lock_token=_token, heartbeat_at=now(), started_at=now(), ended_at=null where chat_id=_chat_id;
  else
    insert into public.agent_sessions (chat_id, project_id, user_id, status, lock_token, heartbeat_at, started_at)
    values (_chat_id, _chat.project_id, _uid, 'running', _token, now(), now());
  end if;
  return _token;
end $$;

create or replace function public.release_agent_lock(_chat_id uuid, _token text, _status text default 'idle') returns void
language sql security definer set search_path = public as $$
  update public.agent_sessions set status = coalesce(_status,'idle'), lock_token = null, ended_at = now()
  where chat_id = _chat_id and lock_token = _token and user_id = auth.uid();
$$;

create or replace function public.approve_agent_plan(_plan_id uuid, _expected_hash text) returns uuid
language plpgsql security definer set search_path = public as $$
declare _p record; _job uuid;
begin
  select * into _p from public.agent_plans where id = _plan_id and user_id = auth.uid() for update;
  if not found then raise exception 'plan not found'; end if;
  if _p.plan_hash <> _expected_hash then raise exception 'plan changed; review it again'; end if;
  if _p.status = 'approved' then select id into _job from public.agent_jobs where plan_id = _plan_id; return _job; end if;
  if _p.status <> 'pending' then raise exception 'plan is %', _p.status; end if;
  update public.agent_plans set status='approved', approved_at=now() where id=_plan_id;
  insert into public.agent_jobs (plan_id, chat_id, project_id, user_id) values (_plan_id, _p.chat_id, _p.project_id, _p.user_id) returning id into _job;
  return _job;
end $$;

create or replace function public.reject_agent_plan(_plan_id uuid, _expected_hash text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update public.agent_plans set status='rejected' where id=_plan_id and user_id=auth.uid() and plan_hash=_expected_hash and status='pending';
  return found;
end $$;

create or replace function public.request_agent_job_cancel(_job_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update public.agent_jobs set cancel_requested_at = coalesce(cancel_requested_at, now()), updated_at = now()
  where id=_job_id and user_id=auth.uid();
  return found;
end $$;

create or replace function public.claim_agent_job_v2(_worker_id text, _stale_seconds integer default 300) returns setof public.agent_jobs
language plpgsql security definer set search_path = public as $$
declare _id uuid;
begin
  select id into _id from public.agent_jobs
  where cancel_requested_at is null and attempts < max_attempts and (
    (status='queued' and available_at <= now()) or
    (status='running' and coalesce(heartbeat_at, started_at) < now() - make_interval(secs => _stale_seconds)))
  order by available_at limit 1 for update skip locked;
  if _id is null then return; end if;
  return query update public.agent_jobs set status='running', worker_id=_worker_id, attempts=attempts+1,
    lease_generation=lease_generation+1, started_at=coalesce(started_at, now()), heartbeat_at=now(), updated_at=now()
  where id=_id returning *;
end $$;
create or replace function public.claim_agent_job(_worker_id text, _stale_seconds integer default 300) returns setof public.agent_jobs
language sql security definer set search_path = public as $$ select * from public.claim_agent_job_v2(_worker_id, _stale_seconds) $$;

create or replace function public.heartbeat_agent_job_v2(_job_id uuid, _worker_id text, _lease_generation integer) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update public.agent_jobs set heartbeat_at=now(), updated_at=now()
  where id=_job_id and worker_id=_worker_id and lease_generation=_lease_generation and status='running' and cancel_requested_at is null;
  return found;
end $$;
create or replace function public.heartbeat_agent_job(_job_id uuid, _worker_id text) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update public.agent_jobs set heartbeat_at=now(), updated_at=now() where id=_job_id and worker_id=_worker_id and status='running' and cancel_requested_at is null;
  return found;
end $$;

create or replace function public.finish_agent_job_v2(_job_id uuid, _worker_id text, _lease_generation integer, _status text,
  _last_error text default null, _checkpoint_id uuid default null, _available_at timestamptz default null) returns boolean
language plpgsql security definer set search_path = public as $$
begin
  update public.agent_jobs set
    status = case when _status in ('retry','queued') then 'queued' else _status end,
    last_error = _last_error, checkpoint_id = coalesce(_checkpoint_id, checkpoint_id),
    available_at = coalesce(_available_at, available_at),
    finished_at = case when _status in ('retry','queued') then null else now() end,
    worker_id = case when _status in ('retry','queued') then null else worker_id end,
    updated_at = now()
  where id=_job_id and worker_id=_worker_id and lease_generation=_lease_generation and status='running';
  return found;
end $$;
create or replace function public.finish_agent_job(_job_id uuid, _worker_id text, _status text,
  _last_error text default null, _checkpoint_id uuid default null, _available_at timestamptz default null) returns boolean
language plpgsql security definer set search_path = public as $$
declare _lg integer;
begin
  select lease_generation into _lg from public.agent_jobs where id=_job_id;
  return public.finish_agent_job_v2(_job_id, _worker_id, _lg, _status, _last_error, _checkpoint_id, _available_at);
end $$;

create or replace function public.save_agent_job_checkpoint(_job_id uuid, _worker_id text, _lease_generation integer, _sequence integer,
  _step_id text, _state jsonb, _state_hash text) returns uuid
language plpgsql security definer set search_path = public as $$
declare _j record; _id uuid;
begin
  select * into _j from public.agent_jobs where id=_job_id and worker_id=_worker_id and lease_generation=_lease_generation and status='running' for update;
  if not found then raise exception 'lease lost'; end if;
  insert into public.agent_job_checkpoints (job_id, user_id, lease_generation, sequence, step_id, state, state_hash)
  values (_job_id, _j.user_id, _lease_generation, _sequence, _step_id, _state, _state_hash) returning id into _id;
  update public.agent_jobs set checkpoint_id=_id, heartbeat_at=now(), updated_at=now() where id=_job_id;
  return _id;
end $$;

revoke execute on function public.claim_agent_job_v2(text,integer), public.claim_agent_job(text,integer),
  public.heartbeat_agent_job_v2(uuid,text,integer), public.heartbeat_agent_job(uuid,text),
  public.finish_agent_job_v2(uuid,text,integer,text,text,uuid,timestamptz), public.finish_agent_job(uuid,text,text,text,uuid,timestamptz),
  public.save_agent_job_checkpoint(uuid,text,integer,integer,text,jsonb,text) from public, anon, authenticated;
grant execute on function public.claim_agent_job_v2(text,integer), public.claim_agent_job(text,integer),
  public.heartbeat_agent_job_v2(uuid,text,integer), public.heartbeat_agent_job(uuid,text),
  public.finish_agent_job_v2(uuid,text,integer,text,text,uuid,timestamptz), public.finish_agent_job(uuid,text,text,text,uuid,timestamptz),
  public.save_agent_job_checkpoint(uuid,text,integer,integer,text,jsonb,text) to service_role;
revoke execute on function public.acquire_agent_lock(uuid,integer), public.release_agent_lock(uuid,text,text),
  public.approve_agent_plan(uuid,text), public.reject_agent_plan(uuid,text), public.request_agent_job_cancel(uuid),
  public.owns_project(uuid), public.owns_cognitive_motor(uuid), public.handle_new_user() from public, anon;
grant execute on function public.acquire_agent_lock(uuid,integer), public.release_agent_lock(uuid,text,text),
  public.approve_agent_plan(uuid,text), public.reject_agent_plan(uuid,text), public.request_agent_job_cancel(uuid),
  public.owns_project(uuid), public.owns_cognitive_motor(uuid) to authenticated, service_role;

create or replace function public.get_published_site(_slug text)
returns table (html text, release_number integer, commit_sha text, activated_at timestamptz)
language sql stable security definer set search_path = public as $$
  select r.artifact_html, r.release_number, r.commit_sha, r.activated_at
  from public.publications p join public.publication_releases r on r.id = p.active_release_id
  where p.slug = _slug and p.status = 'live' and r.artifact_html is not null
$$;
grant execute on function public.get_published_site(text) to anon, authenticated, service_role;

create or replace function public.devstudio_schema_status()
returns table (table_name text, exists_flag boolean, rls_enabled boolean, policy_count integer)
language sql stable security definer set search_path = public as $$
  select t.name, c.oid is not null, coalesce(c.relrowsecurity,false),
    (select count(*)::int from pg_policies p where p.schemaname='public' and p.tablename=t.name)
  from unnest(array['agent_events','agent_job_checkpoints','agent_jobs','agent_plans','agent_sessions','api_connections','audit_logs','chat_messages','chats','checkpoints','cognitive_conversations','cognitive_documents','cognitive_file_contents','cognitive_knowledge','cognitive_knowledge_sources','cognitive_learning_events','cognitive_memory_index','cognitive_messages','cognitive_motor_settings','cognitive_motors','deployment_domains','deployment_logs','deployments','development_logs','development_tasks','file_changes','migration_history','preview_logs','preview_sessions','profiles','project_memory','projects','publication_releases','publications','repositories','repository_snapshots','site_records','test_results']) as t(name)
  left join pg_class c on c.relname = t.name and c.relnamespace = 'public'::regnamespace and c.relkind = 'r'
  order by t.name
$$;
create or replace function public.devstudio_installed_version()
returns table (name text, version text, applied_at timestamptz)
language sql stable security definer set search_path = public as $$
  select name, version, applied_at from public.migration_history order by applied_at desc
$$;
revoke execute on function public.devstudio_schema_status(), public.devstudio_installed_version() from public, anon;
grant execute on function public.devstudio_schema_status(), public.devstudio_installed_version() to authenticated, service_role;
insert into public.migration_history (name, version, description) values ('lovable_cloud_base', '1.0.0', 'Base schema rebuilt in Lovable Cloud');

create or replace function public.search_cognitive_knowledge(_motor_id uuid, _query text, _include_global boolean, _limit integer default 12)
returns table (id uuid, motor_id uuid, motor_name text, title text, content text, category text, kind text, validation text, visibility text, version integer, is_global boolean, rank real)
language plpgsql stable security invoker set search_path = public as $$
declare _q tsquery;
begin
  _q := nullif(replace(plainto_tsquery('simple', left(coalesce(_query,''), 4000))::text, ' & ', ' | '), '')::tsquery;
  return query
  select k.id, k.motor_id, m.name, k.title, k.content, k.category, k.kind, k.validation, k.visibility, k.version,
    (k.motor_id <> _motor_id),
    case when _q is null then 0::real else ts_rank(k.search, _q) end
  from public.cognitive_knowledge k join public.cognitive_motors m on m.id = k.motor_id
  where k.user_id = auth.uid() and k.status <> 'superseded'
    and (k.motor_id = _motor_id or (_include_global and k.visibility = 'global'))
    and (_q is null or k.search @@ _q)
  order by 12 desc, k.updated_at desc
  limit greatest(1, least(coalesce(_limit,12), 100));
end $$;
grant execute on function public.search_cognitive_knowledge(uuid,text,boolean,integer) to authenticated, service_role;

create index on public.cognitive_knowledge using gin (search);
create index on public.agent_events (chat_id, id);
create index on public.chat_messages (chat_id, created_at);
create index on public.agent_jobs (status, available_at);
create index on public.site_records (repository_id, collection, created_at);

alter publication supabase_realtime add table public.agent_events, public.agent_sessions, public.chat_messages, public.agent_plans;